  box-shadow: var(--shadow);
}

.index-hours-card h3 {
  color: var(--color-white);
  margin-bottom: var(--spacing-sm);
}

.index-hours-time {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--color-accent-on-dark);
}

.index-hours-note {
  text-align: center;
  color: var(--color-text-light);
  font-size: 0.95rem;
}

.index-hours-note a {
  color: var(--color-accent-on-dark);
  font-weight: 600;
}

.index-hours-note a:hover,
.index-hours-note a:focus {
  color: var(--color-white);
}

.index-contact {
  background-color: var(--color-neutral-light);
}

.index-contact-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: var(--spacing-xl);
  margin-top: var(--spacing-lg);
}

.index-contact-info {
  background-color: var(--color-white);
  padding: var(--spacing-lg);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
}

.index-contact-info h3 {
  color: var(--color-primary);
  margin-bottom: var(--spacing-lg);
}

.index-contact-details {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-md);
}

.index-contact-item {
  padding-bottom: var(--spacing-sm);
}

.index-contact-item strong {
  color: var(--color-primary);
  display: block;
  margin-bottom: 0.25rem;
}

.index-contact-item p {
  margin-bottom: 0;
  color: var(--color-neutral-dark);
}

.index-contact-item a {
  color: var(--color-accent-dark);
  font-weight: 600;
}

.index-contact-item a:hover,
.index-contact-item a:focus {
  color: var(--color-primary-light);
}

.index-contact-form {
  background-color: var(--color-white);
  padding: var(--spacing-lg);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
}

.index-contact-form h3 {
  color: var(--color-primary);
  margin-bottom: var(--spacing-lg);
}

.index-contact-form input[type="text"],
.index-contact-form input[type="email"],
.index-contact-form input[type="tel"],
.index-contact-form textarea {
  width: 100%;
  padding: 0.75rem;
  margin-bottom: var(--spacing-md);
  border: 1px solid #ddd;
  border-radius: var(--radius);
  font-family: var(--font-sans);
  font-size: 1rem;
  transition: border-color 0.2s ease, box-shadow 0.2s ease;
}

.index-contact-form input[type="text"]:focus,
.index-contact-form input[type="email"]:focus,
.index-contact-form input[type="tel"]:focus,
.index-contact-form textarea:focus {
  outline: none;
  border-color: var(--color-primary);
  box-shadow: 0 0 0 3px rgba(26, 71, 42, 0.1);
}

.index-contact-form textarea {
  resize: vertical;
  min-height: 120px;
}

@media (max-width: 600px) {
  .index-hours-grid {
    grid-template-columns: 1fr;
  }

  .index-contact-grid {
    grid-template-columns: 1fr;
  }

  .index-hours-card {
    padding: var(--spacing-md);
  }

  .index-hours-time {
    font-size: 1.3rem;
  }
}

@media (min-width: 601px) {
  .index-hours-grid {
    grid-template-columns: repeat(3, 1fr);
  }

  .index-contact-grid {
    grid-template-columns: 1fr 1fr;
  }
}
